8: package io.camunda.zeebe.engine.state.batchoperation;
9: 
10: import io.camunda.zeebe.db.ColumnFamily;
11: import io.camunda.zeebe.db.TransactionContext;
12: import io.camunda.zeebe.db.ZeebeDb;
13: import io.camunda.zeebe.db.impl.DbCompositeKey;
14: import io.camunda.zeebe.db.impl.DbForeignKey;
15: import io.camunda.zeebe.db.impl.DbLong;
16: import io.camunda.zeebe.db.impl.DbNil;
17: import io.camunda.zeebe.engine.state.batchoperation.PersistedBatchOperation.BatchOperationStatus;
18: import io.camunda.zeebe.engine.state.mutable.MutableBatchOperationState;
19: import io.camunda.zeebe.protocol.ZbColumnFamilies;
20: import io.camunda.zeebe.protocol.impl.record.value.batchoperation.BatchOperationCreationRecord;
21: import java.util.List;
22: import java.util.Optional;
23: import java.util.Set;
24: import org.slf4j.Logger;
25: import org.slf4j.LoggerFactory;
26: 
27: public class DbBatchOperationState implements MutableBatchOperationState {
28: 
29:   public static final long MAX_DB_CHUNK_SIZE = 3500;
30: 
31:   private static final Logger LOGGER = LoggerFactory.getLogger(DbBatchOperationState.class);
32: 
33:   private final DbLong batchKey = new DbLong();
34:   private final DbForeignKey<DbLong> fkBatchKey;
35:   private final DbLong chunkKey;
36:   private final DbCompositeKey<DbForeignKey<DbLong>, DbLong> fkBatchKeyAndChunkKey;
37: 
38:   private final ColumnFamily<DbLong, PersistedBatchOperation> batchOperationColumnFamily;
39:   private final ColumnFamily<
40:           DbCompositeKey<DbForeignKey<DbLong>, DbLong>, PersistedBatchOperationChunk>
41:       batchOperationChunksColumnFamily;
42:   private final ColumnFamily<DbLong, DbNil> pendingBatchOperationColumnFamily;
43: 
44:   public DbBatchOperationState(
45:       final ZeebeDb<ZbColumnFamilies> zeebeDb, final TransactionContext transactionContext) {
46:     fkBatchKey = new DbForeignKey<>(batchKey, ZbColumnFamilies.BATCH_OPERATION);
47:     chunkKey = new DbLong();
48:     fkBatchKeyAndChunkKey = new DbCompositeKey<>(fkBatchKey, chunkKey);
49: 
50:     batchOperationColumnFamily =
51:         zeebeDb.createColumnFamily(
52:             ZbColumnFamilies.BATCH_OPERATION,
53:             transactionContext,
54:             batchKey,
55:             new PersistedBatchOperation());
56:     batchOperationChunksColumnFamily =
57:         zeebeDb.createColumnFamily(
58:             ZbColumnFamilies.BATCH_OPERATION_CHUNKS,
59:             transactionContext,
60:             fkBatchKeyAndChunkKey,
61:             new PersistedBatchOperationChunk());
62:     pendingBatchOperationColumnFamily =
63:         zeebeDb.createColumnFamily(
64:             ZbColumnFamilies.PENDING_BATCH_OPERATION, transactionContext, batchKey, DbNil.INSTANCE);
65:   }
66: 
67:   @Override
68:   public void create(final long batchOperationKey, final BatchOperationCreationRecord record) {
69:     LOGGER.debug("Creating batch operation with key {}", record.getBatchOperationKey());
70:     batchKey.wrapLong(record.getBatchOperationKey());
71:     final var batchOperation = new PersistedBatchOperation();
72:     batchOperation.wrap(record).setStatus(BatchOperationStatus.CREATED);
73:     batchOperationColumnFamily.upsert(batchKey, batchOperation);
74:     pendingBatchOperationColumnFamily.upsert(batchKey, DbNil.INSTANCE);
75:   }
76: 
77:   @Override
78:   public void start(final long batchOperationKey) {
79:     LOGGER.debug("Starting batch operation with key {}", batchOperationKey);
80:     batchKey.wrapLong(batchOperationKey);
81:     final var batchOperation = get(batchOperationKey);
82:     if (batchOperation.isPresent()) {
83:       batchOperation.get().setStatus(BatchOperationStatus.STARTED);
84:       batchOperation.get().markAsInitialized();
85:       batchOperationColumnFamily.update(batchKey, batchOperation.get());
86:       pendingBatchOperationColumnFamily.deleteIfExists(batchKey);
87:     } else {
88:       LOGGER.error("Batch operation with key {} not found, cannot start it.", batchOperationKey);
89:     }
90:   }
91: 
92:   @Override
93:   public void fail(final long batchOperationKey) {
94:     LOGGER.debug("Failing batch operation with key {}", batchOperationKey);
95:     batchKey.wrapLong(batchOperationKey);
96:     final var batchOperation = get(batchOperationKey);
97:     if (batchOperation.isPresent()) {
98:       batchOperation.get().setStatus(BatchOperationStatus.FAILED);
99:       batchOperationColumnFamily.update(batchKey, batchOperation.get());
100:       pendingBatchOperationColumnFamily.deleteIfExists(batchKey);
101:     } else {
102:       LOGGER.error("Batch operation with key {} not found, cannot fail it.", batchOperationKey);
103:     }
104:   }
105: 
106:   @Override
107:   public void appendItemKeys(final long batchOperationKey, final Set<Long> itemKeys) {
108:     LOGGER.trace(
109:         "Appending {} item keys to batch operation with key {}",
110:         itemKeys.size(),
111:         batchOperationKey);
112: 
113:     // First, get the batch operation
114:     final var batch = get(batchOperationKey);
115:     if (batch.isEmpty()) {
116:       LOGGER.error(
117:           "Batch operation with key {} not found, cannot append itemKeys to it.",
118:           batchOperationKey);
119:       return;
120:     }
121: 
122:     // Second, get the chunk to append the keys to
123:     var chunk = getOrCreateChunk(batch.get());
124: 
125:     // Third, append the keys to the chunk, if the chunk is full, a new one is returned
126:     for (final long key : itemKeys) {
127:       chunk = appendKeyToChunk(batch.get(), chunk, key);
128:     }
129: 
130:     // Finally, update the batch and the chunk in the column family
131:     updateChunkAndBatch(chunk, batch.get());
132:   }
133: 
134:   @Override
135:   public void removeItemKeys(final long batchOperationKey, final Set<Long> itemKeys) {
136:     LOGGER.trace(
137:         "Removing item keys {} from batch operation with key {}",
138:         itemKeys.size(),
139:         batchOperationKey);
140: 
141:     // First, get the batch operation
142:     final var batch = get(batchOperationKey);
143:     if (batch.isEmpty()) {
144:       LOGGER.error(
145:           "Batch operation with key {} not found, cannot remove itemKeys from it.",
146:           batchOperationKey);
147:       return;
148:     }
149: 
150:     // Second, delete the keys from chunk
151:     final var chunk = getMinChunk(batch.get());
152:     chunk.removeItemKeys(itemKeys);
153: 
154:     // Finally, update the chunk and batch in the column family
155:     updateBatchAndChunkAfterRemoval(batch.get(), chunk);
156:   }
157: 
158:   @Override
159:   public void cancel(final long batchOperationKey) {
160:     LOGGER.trace("Cancel batch operation with key {}", batchOperationKey);
161:     deleteBatchOperation(batchOperationKey);
162:   }
163: 
164:   @Override
165:   public void pause(final long batchOperationKey) {
166:     LOGGER.trace("Pausing batch operation with key {}", batchOperationKey);
167:     batchKey.wrapLong(batchOperationKey);
168: 
169:     // Set status to PAUSED
170:     final var batch = batchOperationColumnFamily.get(batchKey);
171:     batch.setStatus(BatchOperationStatus.PAUSED);
172:     batchOperationColumnFamily.update(batchKey, batch);
173:   }
174: 
175:   @Override
176:   public void resume(final long batchOperationKey) {
177:     LOGGER.trace("Resume batch operation with key {}", batchOperationKey);
178:     batchKey.wrapLong(batchOperationKey);
179: 
180:     // Set status to STARTED
181:     final var batch = batchOperationColumnFamily.get(batchKey);
182:     batch.setStatus(
183:         batch.isInitialized() ? BatchOperationStatus.STARTED : BatchOperationStatus.CREATED);
184:     batchOperationColumnFamily.update(batchKey, batch);
185:   }
186: 
187:   @Override
188:   public void complete(final long batchOperationKey) {
189:     LOGGER.trace("Completing batch operation with key {}", batchOperationKey);
190:     deleteBatchOperation(batchOperationKey);
191:   }
192: 
193:   @Override
194:   public boolean exists(final long batchOperationKey) {
195:     return get(batchOperationKey).isPresent();
196:   }
197: 
198:   @Override
199:   public Optional<PersistedBatchOperation> get(final long key) {
200:     batchKey.wrapLong(key);
201:     return Optional.ofNullable(batchOperationColumnFamily.get(batchKey));
202:   }
203: 
204:   @Override
205:   public void foreachPendingBatchOperation(final BatchOperationVisitor visitor) {
206:     pendingBatchOperationColumnFamily.whileTrue(
207:         (key, nil) -> {
208:           final var batchOperation = batchOperationColumnFamily.get(key);
209:           if (batchOperation != null) {
210:             visitor.visit(batchOperation);
211:           }
212:           return true;
213:         });
214:   }
215: 
216:   @Override
217:   public List<Long> getNextItemKeys(final long batchOperationKey, final int batchSize) {
218:     final var batch = get(batchOperationKey);
219:     if (batch.isEmpty()) {
220:       LOGGER.error(
221:           "Batch operation with key {} not found, cannot get next item keys.", batchOperationKey);
222:       return List.of();
223:     }
224: 
225:     if (batch.get().getMinChunkKey() == -1) {
226:       return List.of();
227:     }
228: 
229:     chunkKey.wrapLong(batch.get().getMinChunkKey());
230:     final var chunk = batchOperationChunksColumnFamily.get(fkBatchKeyAndChunkKey);
231:     final var chunkKeys = chunk.getItemKeys();
232: 
233:     return chunkKeys.stream().limit(batchSize).toList();
234:   }
235: 
236:   /** This deletes everything related to the batch operation. */
237:   private void deleteBatchOperation(final long batchOperationKey) {
238:     batchKey.wrapLong(batchOperationKey);
239: 
240:     // first delete the batch operation from the pendingBatchOperationColumnFamily if it exists
241:     pendingBatchOperationColumnFamily.deleteIfExists(batchKey);
242: 
243:     // then delete all chunks
244:     batchOperationChunksColumnFamily.whileEqualPrefix(
245:         batchKey,
246:         (compositeKey, entityTypeValue) -> {
247:           batchOperationChunksColumnFamily.deleteExisting(compositeKey);
248:         });
249: 
250:     // finally delete batch operation itself
251:     batchOperationColumnFamily.deleteExisting(batchKey);
252:   }
253: 
254:   private PersistedBatchOperationChunk createNewChunk(final PersistedBatchOperation batch) {
255:     final var currentChunkKey = batch.nextChunkKey();
256:     batch.addChunkKey(currentChunkKey);
257: 
258:     final var batchChunk = new PersistedBatchOperationChunk();
259:     batchChunk.setKey(currentChunkKey).setBatchOperationKey(batch.getKey());
260:     chunkKey.wrapLong(batchChunk.getKey());
261: 
262:     batchOperationChunksColumnFamily.insert(fkBatchKeyAndChunkKey, batchChunk);
263: 
264:     return batchChunk;
265:   }
266: 
267:   /** Returns the chunk for min chunk key */
268:   private PersistedBatchOperationChunk getMinChunk(final PersistedBatchOperation batch) {
269:     chunkKey.wrapLong(batch.getMinChunkKey());
270:     return batchOperationChunksColumnFamily.get(fkBatchKeyAndChunkKey);
271:   }
272: 
273:   /**
274:    * Updates the batch and chunk after removing keys from the chunk. If the chunk is empty, it is
275:    * deleted from the column family and the batch operation is updated.
276:    *
277:    * @param chunk the chunk to update
278:    * @param batch the batch operation to update
279:    */
280:   private void updateBatchAndChunkAfterRemoval(
281:       final PersistedBatchOperation batch, final PersistedBatchOperationChunk chunk) {
282:     if (chunk.getItemKeys().isEmpty()) {
283:       batchOperationChunksColumnFamily.deleteExisting(fkBatchKeyAndChunkKey);
284:       batch.removeChunkKey(chunk.getKey());
285:       batchOperationColumnFamily.update(batchKey, batch);
286:     } else {
287:       batchOperationChunksColumnFamily.update(fkBatchKeyAndChunkKey, chunk);
288:     }
289:   }
290: 
291:   /**
292:    * Gets the chunk for the batch operation. If the batch operation has no chunk (currentChunkKey =
293:    * -1), a new one is created.
294:    *
295:    * @param batch the batch operation to get the chunk for
296:    * @return the chunk for the batch operation
297:    */
298:   private PersistedBatchOperationChunk getOrCreateChunk(final PersistedBatchOperation batch) {
299:     final var currentChunkKey = batch.getMinChunkKey();
300:     if (currentChunkKey == -1) {
301:       return createNewChunk(batch);
302:     } else {
303:       chunkKey.wrapLong(currentChunkKey);
304:       return batchOperationChunksColumnFamily.get(fkBatchKeyAndChunkKey);
305:     }
306:   }
307: 
308:   /**
309:    * Appends the key to the chunk. If the chunk is full, a new one is created.
310:    *
311:    * @param chunk the current chunk to append the keys to, if it is full, a new one is created
312:    * @param key the key to append
313:    * @return the current updated chunk
314:    */
315:   private PersistedBatchOperationChunk appendKeyToChunk(
316:       final PersistedBatchOperation batch, PersistedBatchOperationChunk chunk, final long key) {
317:     if (chunk.getItemKeys().size() >= MAX_DB_CHUNK_SIZE) {
318:       batchOperationChunksColumnFamily.update(fkBatchKeyAndChunkKey, chunk);
319:       chunk = createNewChunk(batch);
320:     }
321: 
322:     chunk.appendItemKey(key);
323:     return chunk;
324:   }
325: 
326:   private void updateChunkAndBatch(
327:       final PersistedBatchOperationChunk chunk, final PersistedBatchOperation batch) {
328:     if (chunk != null) {
329:       batchOperationChunksColumnFamily.update(fkBatchKeyAndChunkKey, chunk);
330:     }
331:     batchOperationColumnFamily.update(batchKey, batch);
