108:   public List<ProcessInstanceEntity> callHierarchy(final long processInstanceKey) {
109:     final var rootInstance = getByKey(processInstanceKey);
110: 
111:     final var treePath = rootInstance.treePath();
112:     if (treePath == null || treePath.isBlank()) {
113:       return List.of();
114:     }
115: 
116:     final List<Long> orderedKeys =
117:         TreePathParser.extractProcessInstanceKeys(rootInstance.treePath()).stream().toList();
118: 
119:     if (orderedKeys.size() == 1
120:         && orderedKeys.getFirst().equals(rootInstance.processInstanceKey())) {
121:       return List.of();
122:     }
123: 
124:     final var resultsByKey =
125:         processInstanceSearchClient
126:             .searchProcessInstances(
127:                 processInstanceSearchQuery(
128:                     q -> q.filter(f -> f.processInstanceKeyOperations(Operation.in(orderedKeys)))))
129:             .items()
130:             .stream()
131:             .collect(
132:                 Collectors.toMap(ProcessInstanceEntity::processInstanceKey, Function.identity()));
133: 
134:     return orderedKeys.stream().map(resultsByKey::get).filter(Objects::nonNull).toList();
135:   }
