213:           .ifPresent(builder::stateOperations);
214:       ofNullable(filter.getHasIncident()).ifPresent(builder::hasIncident);
215:       ofNullable(filter.getTenantId())
216:           .map(mapToOperations(String.class))
217:           .ifPresent(builder::tenantIdOperations);
