1516:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER));
1517:     }
1518:     if (requestedPage.getFrom() != null && (searchAfter != null || searchBefore != null)) {
1519:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER_AND_FROM));
