403:   private static void addDeploymentRelatedProcessorAndServices(
404:       final BpmnBehaviorsImpl bpmnBehaviors,
405:       final ProcessingState processingState,
406:       final Supplier<ScheduledTaskState> scheduledTaskStateSupplier,
407:       final TypedRecordProcessors typedRecordProcessors,
408:       final Writers writers,
409:       final DeploymentDistributionCommandSender deploymentDistributionCommandSender,
410:       final KeyGenerator keyGenerator,
411:       final FeatureFlags featureFlags,
412:       final CommandDistributionBehavior distributionBehavior,
413:       final EngineConfiguration config,
414:       final InstantSource clock,
415:       final AuthorizationCheckBehavior authCheckBehavior,
416:       final RoutingInfo routingInfo) {
417: 
418:     // on deployment partition CREATE Command is received and processed
419:     // it will cause a distribution to other partitions
420:     final var processor =
421:         new DeploymentCreateProcessor(
422:             processingState,
423:             bpmnBehaviors,
424:             writers,
425:             keyGenerator,
426:             featureFlags,
427:             distributionBehavior,
428:             config,
429:             clock,
430:             authCheckBehavior);
431: 
432:     typedRecordProcessors.onCommand(ValueType.DEPLOYMENT, CREATE, processor);
433: 
434:     // periodically retries deployment distribution
435:     final var deploymentRedistributor =
436:         new DeploymentRedistributor(
437:             deploymentDistributionCommandSender,
438:             scheduledTaskStateSupplier.get().getDeploymentState(),
439:             routingInfo);
440:     typedRecordProcessors.withListener(deploymentRedistributor);
441: 
442:     // on other partitions DISTRIBUTE command is received and processed
443:     final DeploymentDistributeProcessor deploymentDistributeProcessor =
444:         new DeploymentDistributeProcessor(
445:             processingState, deploymentDistributionCommandSender, writers, keyGenerator);
446:     typedRecordProcessors.onCommand(
447:         ValueType.DEPLOYMENT, DeploymentIntent.DISTRIBUTE, deploymentDistributeProcessor);
448: 
449:     // completes the deployment distribution
450:     final var completeDeploymentDistributionProcessor =
451:         new DeploymentDistributionCompleteProcessor(processingState.getDeploymentState(), writers);
452:     typedRecordProcessors.onCommand(
453:         ValueType.DEPLOYMENT_DISTRIBUTION,
454:         DeploymentDistributionIntent.COMPLETE,
455:         completeDeploymentDistributionProcessor);
456: 
457:     typedRecordProcessors.onCommand(
458:         ValueType.DEPLOYMENT,
459:         DeploymentIntent.RECONSTRUCT,
460:         new DeploymentReconstructProcessor(keyGenerator, processingState, writers));
461: 
462:     typedRecordProcessors.withListener(
463:         new DeploymentReconstructionStarter(processingState.getDeploymentState()));
464:   }
