391:   private ElementInstance getUserTaskElementInstance(final UserTaskRecord userTaskRecord) {
392:     final var elementInstanceKey = userTaskRecord.getElementInstanceKey();
393:     return elementInstanceState.getInstance(elementInstanceKey);
394:   }
