44: @ExcludeAuthorizationCheck
45: public class UserTaskProcessor implements TypedRecordProcessor<UserTaskRecord> {
46: 
47:   private static final String USER_TASK_COMPLETION_REJECTION =
48:       "Completion of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
49: 
50:   private static final String USER_TASK_ASSIGNMENT_REJECTION =
51:       "Assignment of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
52: 
53:   private static final String USER_TASK_UPDATE_REJECTION =
54:       "Update of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
55: 
56:   private static final String USER_TASK_VARIABLE_UPDATE_REJECTION =
57:       "Variable update for user task instance with key '%d' was denied by Task Listener. Reason to deny: '%s'";
58: 
59:   private final UserTaskCommandProcessors commandProcessors;
60:   private final ProcessState processState;
61:   private final MutableUserTaskState userTaskState;
62:   private final ElementInstanceState elementInstanceState;
63:   private final VariableState variableState;
64: 
65:   private final BpmnJobBehavior jobBehavior;
66: 
67:   private final TypedRejectionWriter rejectionWriter;
68:   private final TypedResponseWriter responseWriter;
69:   private final StateWriter stateWriter;
70: 
71:   public UserTaskProcessor(
72:       final ProcessingState state,
73:       final MutableUserTaskState userTaskState,
74:       final KeyGenerator keyGenerator,
75:       final BpmnBehaviors bpmnBehaviors,
76:       final Writers writers,
77:       final AuthorizationCheckBehavior authCheckBehavior) {
78:     commandProcessors =
79:         new UserTaskCommandProcessors(
80:             state, keyGenerator, bpmnBehaviors, writers, authCheckBehavior);
81:     processState = state.getProcessState();
82:     this.userTaskState = userTaskState;
83:     elementInstanceState = state.getElementInstanceState();
84:     variableState = state.getVariableState();
85: 
86:     jobBehavior = bpmnBehaviors.jobBehavior();
87: 
88:     rejectionWriter = writers.rejection();
89:     responseWriter = writers.response();
90:     stateWriter = writers.state();
91:   }
92: 
93:   @Override
94:   public void processRecord(final TypedRecord<UserTaskRecord> command) {
95:     final UserTaskIntent intent = (UserTaskIntent) command.getIntent();
96:     switch (intent) {
97:       case CREATE, ASSIGN, CLAIM, UPDATE, COMPLETE, CANCEL ->
98:           processOperationCommand(command, intent);
99:       case COMPLETE_TASK_LISTENER -> processCompleteTaskListener(command);
100:       case DENY_TASK_LISTENER -> processDenyTaskListener(command);
101:       default -> throw new UnsupportedOperationException("Unexpected user task intent: " + intent);
102:     }
103:   }
104: 
105:   private void processCompleteTaskListener(final TypedRecord<UserTaskRecord> command) {
106:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
107:     final var listenerEventType = mapLifecycleStateToEventType(lifecycleState);
108:     // we need to copy the intermediate user task record as we have read it from the state, and we
109:     // will read from the state again later, which in turn would modify this record
110:     final var intermediateUserTaskRecord =
111:         userTaskState.getIntermediateState(command.getKey()).getRecord().copy();
112:     final var userTaskElement = getUserTaskElement(intermediateUserTaskRecord);
113:     final var userTaskElementInstance = getUserTaskElementInstance(intermediateUserTaskRecord);
114:     final var context = buildContext(userTaskElementInstance);
115: 
116:     if (command.getValue().hasChangedAttributes()) {
117:       intermediateUserTaskRecord.wrapChangedAttributesIfValueChanged(command.getValue());
118: 
119:       if (intermediateUserTaskRecord.hasChangedAttributes()) {
120:         stateWriter.appendFollowUpEvent(
121:             command.getKey(), UserTaskIntent.CORRECTED, intermediateUserTaskRecord);
122:       }
123:     }
124: 
125:     findNextTaskListener(listenerEventType, userTaskElement, userTaskElementInstance)
126:         .ifPresentOrElse(
127:             listener -> {
128:               final var currentUserTask = userTaskState.getUserTask(command.getKey());
129:               final var changedAttributes =
130:                   intermediateUserTaskRecord.determineChangedAttributes(currentUserTask);
131:               jobBehavior.createNewTaskListenerJob(
132:                   context, intermediateUserTaskRecord, listener, changedAttributes);
133:             },
134:             () -> finalizeCommand(command, lifecycleState, intermediateUserTaskRecord));
135:   }
136: 
137:   private void finalizeCommand(
138:       final TypedRecord<UserTaskRecord> command,
139:       final LifecycleState lifecycleState,
140:       final UserTaskRecord userTaskRecord) {
141:     final var currentUserTask = userTaskState.getUserTask(command.getKey());
142:     userTaskRecord.setDiffAsChangedAttributes(currentUserTask);
143: 
144:     final var commandProcessor = determineProcessorFromUserTaskLifecycleState(lifecycleState);
145:     commandProcessor.onFinalizeCommand(command, userTaskRecord);
146:   }
147: 
148:   private void processDenyTaskListener(final TypedRecord<UserTaskRecord> command) {
149:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
150:     final var persistedRecord = userTaskState.getUserTask(command.getKey());
151: 
152:     switch (lifecycleState) {
153:       case COMPLETING ->
154:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.COMPLETION_DENIED);
155:       case ASSIGNING, CLAIMING ->
156:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.ASSIGNMENT_DENIED);
157:       case UPDATING ->
158:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.UPDATE_DENIED);
159:       default ->
160:           throw new IllegalArgumentException(
161:               "Expected to reject operation for user task: '%d', but operation could not be determined from the task's current lifecycle state: '%s'"
162:                   .formatted(command.getValue().getUserTaskKey(), lifecycleState));
163:     }
164:   }
165: 
166:   private void processOperationCommand(
167:       final TypedRecord<UserTaskRecord> command, final UserTaskIntent intent) {
168:     final var commandProcessor = commandProcessors.getCommandProcessor(intent);
169: 
170:     if (isRetriedCommand(command)) {
171:       // Skip `validateCommand` and `onCommand` invocations for retried command,
172:       // as it was already validated during the original execution
173:       finalizeCommandOrCreateTaskListenerJob(commandProcessor, command, command.getValue(), intent);
174:     } else {
175:       commandProcessor
176:           .validateCommand(command)
177:           // Create a modifiable copy of the persisted user task record, as `onCommand` may
178:           // apply the changed attributes from the command on top of persisted instance.
179:           .map(UserTaskRecord::copy)
180:           .thenDo(persistedRecord -> commandProcessor.onCommand(command, persistedRecord))
181:           .ifRightOrLeft(
182:               persistedRecord ->
183:                   finalizeCommandOrCreateTaskListenerJob(
184:                       commandProcessor, command, persistedRecord, intent),
185:               rejection -> handleCommandRejection(command, rejection));
186:     }
187:   }
188: 
189:   private void finalizeCommandOrCreateTaskListenerJob(
190:       final UserTaskCommandProcessor processor,
191:       final TypedRecord<UserTaskRecord> command,
192:       final UserTaskRecord persistedRecord,
193:       final UserTaskIntent intent) {
194: 
195:     final var userTaskElement = getUserTaskElement(persistedRecord);
196:     final var eventType = mapIntentToEventType(intent);
197: 
198:     if (userTaskElement.hasTaskListeners(eventType)) {
199:       /*
200:        * Store the original command's metadata (requestId, requestStreamId) before creating
201:        * the first task listener job. This metadata will be used later to finalize the original
202:        * command after all task listeners have been processed, ensuring that the engine can respond
203:        * appropriately to the original command request.
204:        *
205:        * Note:
206:        * Typically, persistence logic should be handled via `*Applier` classes. However, since
207:        * this involves request-related data, so in the case of command reconstruction,
208:        * we will have new request values anyway, so persisting these data here is acceptable.
209:        * A similar approach has been used in `ProcessInstanceCreationCreateWithResultProcessor`.
210:        */
211:       storeUserTaskRecordRequestMetadata(command);
212: 
213:       final var listener = userTaskElement.getTaskListeners(eventType).getFirst();
214:       final var userTaskElementInstance = getUserTaskElementInstance(persistedRecord);
215:       final var context = buildContext(userTaskElementInstance);
216:       jobBehavior.createNewTaskListenerJob(
217:           context, persistedRecord, listener, persistedRecord.getChangedAttributes());
218:     } else {
219:       processor.onFinalizeCommand(command, persistedRecord);
220:     }
221:   }
222: 
223:   private boolean isRetriedCommand(final TypedRecord<UserTaskRecord> command) {
224:     return command instanceof RetryTypedRecord<UserTaskRecord>;
225:   }
226: 
227:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
228:     if (!command.hasRequestMetadata()) {
229:       return;
230:     }
231: 
232:     final var metadata =
233:         new UserTaskTransitionTriggerRequestMetadata()
234:             .setIntent(command.getIntent())
235:             .setTriggerType(ValueType.USER_TASK)
236:             .setRequestId(command.getRequestId())
237:             .setRequestStreamId(command.getRequestStreamId());
238:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
239:   }
240: 
241:   private void handleCommandRejection(
242:       final TypedRecord<UserTaskRecord> command, final Rejection rejection) {
243:     rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
244:     responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
245:   }
246: 
247:   private Optional<TaskListener> findNextTaskListener(
248:       final ZeebeTaskListenerEventType eventType,
249:       final ExecutableUserTask userTask,
250:       final ElementInstance userTaskElementInstance) {
251:     final var listeners = userTask.getTaskListeners(eventType);
252:     final int currentListenerIndex = userTaskElementInstance.getTaskListenerIndex(eventType);
253:     return listeners.stream().skip(currentListenerIndex).findFirst();
254:   }
255: 
256:   private void writeRejectionForCommand(
257:       final TypedRecord<UserTaskRecord> command,
258:       final UserTaskRecord persistedRecord,
259:       final UserTaskIntent intent) {
260: 
261:     persistedRecord.setDeniedReason(command.getValue().getDeniedReason());
262:     final var recordRequestMetadata =
263:         userTaskState.findAsyncRequest(persistedRecord.getUserTaskKey());
264: 
265:     stateWriter.appendFollowUpEvent(persistedRecord.getUserTaskKey(), intent, persistedRecord);
266:     recordRequestMetadata.ifPresent(
267:         metadata -> {
268:           switch (metadata.getTriggerType()) {
269:             case USER_TASK ->
270:                 responseWriter.writeRejection(
271:                     command.getKey(),
272:                     mapDeniedIntentToResponseIntent(intent),
273:                     command.getValue(),
274:                     command.getValueType(),
275:                     RejectionType.INVALID_STATE,
276:                     mapDeniedIntentToResponseRejectionReason(
277:                         intent,
278:                         persistedRecord.getUserTaskKey(),
279:                         command.getValue().getDeniedReason()),
280:                     metadata.getRequestId(),
281:                     metadata.getRequestStreamId());
282:             case VARIABLE_DOCUMENT -> {
283:               final long userTaskInstanceKey = command.getValue().getElementInstanceKey();
284:               variableState
285:                   .findVariableDocumentState(userTaskInstanceKey)
286:                   .ifPresent(
287:                       variableDocumentState -> {
288:                         final long variableDocumentKey = variableDocumentState.getKey();
289:                         final var variableDocumentRecord = variableDocumentState.getRecord();
290:                         stateWriter.appendFollowUpEvent(
291:                             variableDocumentKey,
292:                             VariableDocumentIntent.UPDATE_DENIED,
293:                             variableDocumentRecord);
294: 
295:                         final var deniedReason =
296:                             USER_TASK_VARIABLE_UPDATE_REJECTION.formatted(
297:                                 userTaskInstanceKey, command.getValue().getDeniedReason());
298:                         responseWriter.writeRejection(
299:                             variableDocumentKey,
300:                             VariableDocumentIntent.UPDATE,
301:                             variableDocumentRecord,
302:                             ValueType.VARIABLE_DOCUMENT,
303:                             RejectionType.INVALID_STATE,
304:                             deniedReason,
305:                             metadata.getRequestId(),
306:                             metadata.getRequestStreamId());
307:                       });
308:             }
309:             default ->
310:                 throw new IllegalArgumentException(
311:                     "Unexpected user task transition trigger type: '%s'"
312:                         .formatted(metadata.getTriggerType()));
313:           }
314:         });
315:   }
316: 
317:   private ExecutableUserTask getUserTaskElement(final UserTaskRecord userTaskRecord) {
318:     return processState.getFlowElement(
319:         userTaskRecord.getProcessDefinitionKey(),
320:         userTaskRecord.getTenantId(),
321:         userTaskRecord.getElementIdBuffer(),
322:         ExecutableUserTask.class);
323:   }
324: 
325:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intent) {
326:     return switch (intent) {
327:       case CREATE -> ZeebeTaskListenerEventType.creating;
328:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
329:       case UPDATE -> ZeebeTaskListenerEventType.updating;
330:       case COMPLETE -> ZeebeTaskListenerEventType.completing;
331:       case CANCEL -> ZeebeTaskListenerEventType.canceling;
332:       default ->
333:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
334:     };
335:   }
336: 
337:   private ZeebeTaskListenerEventType mapLifecycleStateToEventType(
338:       final LifecycleState lifecycleState) {
339:     return switch (lifecycleState) {
340:       case CREATING -> ZeebeTaskListenerEventType.creating;
341:       case ASSIGNING, CLAIMING -> ZeebeTaskListenerEventType.assigning;
342:       case UPDATING -> ZeebeTaskListenerEventType.updating;
343:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
344:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
345:       default ->
346:           throw new IllegalArgumentException(
347:               "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
348:     };
349:   }
350: 
351:   private UserTaskIntent mapDeniedIntentToResponseIntent(final UserTaskIntent intent) {
352:     return switch (intent) {
353:       case COMPLETION_DENIED -> UserTaskIntent.COMPLETE;
354:       case ASSIGNMENT_DENIED -> UserTaskIntent.ASSIGN;
355:       case UPDATE_DENIED -> UserTaskIntent.UPDATE;
356:       default ->
357:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
358:     };
359:   }
360: 
361:   private String mapDeniedIntentToResponseRejectionReason(
362:       final UserTaskIntent intent, final long userTaskKey, final String deniedReason) {
363:     return switch (intent) {
364:       case COMPLETION_DENIED -> USER_TASK_COMPLETION_REJECTION.formatted(userTaskKey, deniedReason);
365:       case ASSIGNMENT_DENIED -> USER_TASK_ASSIGNMENT_REJECTION.formatted(userTaskKey, deniedReason);
366:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
367:       default ->
368:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
369:     };
370:   }
371: 
372:   private UserTaskCommandProcessor determineProcessorFromUserTaskLifecycleState(
373:       final LifecycleState lifecycleState) {
374: 
375:     final var userTaskIntent =
376:         switch (lifecycleState) {
377:           case CREATING -> UserTaskIntent.CREATE;
378:           case ASSIGNING -> UserTaskIntent.ASSIGN;
379:           case CLAIMING -> UserTaskIntent.CLAIM;
380:           case UPDATING -> UserTaskIntent.UPDATE;
381:           case COMPLETING -> UserTaskIntent.COMPLETE;
382:           case CANCELING -> UserTaskIntent.CANCEL;
383:           default ->
384:               throw new IllegalArgumentException(
385:                   "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
386:         };
387: 
388:     return commandProcessors.getCommandProcessor(userTaskIntent);
389:   }
390: 
391:   private ElementInstance getUserTaskElementInstance(final UserTaskRecord userTaskRecord) {
392:     final var elementInstanceKey = userTaskRecord.getElementInstanceKey();
393:     return elementInstanceState.getInstance(elementInstanceKey);
394:   }
395: 
396:   private BpmnElementContext buildContext(final ElementInstance elementInstance) {
397:     final var context = new BpmnElementContextImpl();
398:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
399:     return context;
400:   }
401: }
