63:   public void onCommand(
64:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
65:     final long userTaskKey = command.getKey();
66: 
67:     final var newAssignee = command.getValue().getAssignee();
68:     if (!userTaskRecord.getAssignee().equals(newAssignee)) {
69:       userTaskRecord.setAssignee(newAssignee);
70:       userTaskRecord.setAssigneeChanged();
71:     }
72:     userTaskRecord.setAction(command.getValue().getActionOrDefault(DEFAULT_ACTION));
73: 
74:     stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.CLAIMING, userTaskRecord);
75:   }
