91:       stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.ASSIGNED, userTaskRecord);
92: 
93:       recordRequestMetadata.ifPresent(
94:           metadata ->
95:               responseWriter.writeResponse(
96:                   userTaskKey,
97:                   UserTaskIntent.ASSIGNED,
98:                   userTaskRecord,
99:                   ValueType.USER_TASK,
100:                   metadata.getRequestId(),
101:                   metadata.getRequestStreamId()));
102:     }
103:   }
104: 
105:   private static Either<Rejection, UserTaskRecord> checkClaim(
106:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
107: 
108:     final long userTaskKey = command.getKey();
109:     final String newAssignee = command.getValue().getAssignee();
110:     if (newAssignee.isBlank()) {
111:       return Either.left(
112:           new Rejection(
113:               RejectionType.INVALID_STATE,
114:               String.format(INVALID_USER_TASK_EMPTY_ASSIGNEE_MESSAGE, userTaskKey)));
115:     }
116: 
117:     final String currentAssignee = userTaskRecord.getAssignee();
118:     final boolean canClaim = currentAssignee.isBlank() || currentAssignee.equals(newAssignee);
119:     if (!canClaim) {
120:       return Either.left(
121:           new Rejection(
122:               RejectionType.INVALID_STATE,
123:               String.format(INVALID_USER_TASK_ASSIGNEE_MESSAGE, userTaskKey)));
124:     }
125: 
126:     return Either.right(userTaskRecord);
127:   }
