218:   private static boolean hasVariables(final VariableDocumentRecord record) {
219:     return !DocumentValue.EMPTY_DOCUMENT.equals(record.getVariablesBuffer());
220:   }
221: 
222:   private static boolean isCamundaUserTask(ElementInstance elementInstance) {
223:     return elementInstance.getValue().getBpmnElementType() == BpmnElementType.USER_TASK
224:         && elementInstance.getUserTaskKey() > -1L;
