32: /**
33:  * This class provides methods to fetch entities for batch operations. It uses the search client
34:  * proxy to access the secondary database.
35:  */
36: public class BatchOperationItemProvider {
37: 
38:   private static final Logger LOG = LoggerFactory.getLogger(BatchOperationItemProvider.class);
39: 
40:   private final SearchClientsProxy searchClientsProxy;
41: 
42:   /**
43:    * The size of a page when fetching entities. This is the maximum number of items that can be
44:    * fetched in a single query and is limited by ElasticSearch.
45:    */
46:   private final int queryPageSize;
47: 
48:   /**
49:    * The maximum number of keys that can be passed in a single IN clause in a query. This is limited
50:    * to 1000 because the Oracle DB supports a maximum of 1000 elements in an IN clause.
51:    */
52:   private final int inClauseSize;
53: 
54:   public BatchOperationItemProvider(
55:       final SearchClientsProxy searchClientsProxy, final EngineConfiguration engineConfiguration) {
56:     this.searchClientsProxy = searchClientsProxy;
57:     queryPageSize = engineConfiguration.getBatchOperationQueryPageSize();
58:     inClauseSize = engineConfiguration.getBatchOperationQueryInClauseSize();
59:   }
60: 
61:   /**
62:    * Fetches the process instance items for the given partitionId based on the provided filter. The
63:    * items are fetched sequentially in pages. Depending on the overall size of the result, this can
64:    * cause multiple queries to the secondary database.
65:    *
66:    * @param filter the filter to use
67:    * @param authentication the authentication to use
68:    * @param shouldAbort if the process should be aborted
69:    * @return a set of all found process instance items
70:    */
71:   public Set<Item> fetchProcessInstanceItems(
72:       final int partitionId,
73:       final ProcessInstanceFilter filter,
74:       final Authentication authentication,
75:       final Supplier<Boolean> shouldAbort) {
76:     final var processInstanceFilter = filter.toBuilder().partitionId(partitionId).build();
77: 
78:     LOG.debug(
79:         "Fetching process instance items for partition {} with filter: {}",
80:         partitionId,
81:         processInstanceFilter);
82: 
83:     return fetchEntityItems(
84:         new ProcessInstancePageFetcher(), processInstanceFilter, authentication, shouldAbort);
85:   }
86: 
87:   /**
88:    * Fetches the incident items based on the provided incident filter. The items are fetched
89:    * sequentially in pages. Depending on the overall size of the result this can cause multiple
90:    * queries to the secondary database.
91:    *
92:    * @param filter the filter to use
93:    * @param authentication the authentication to use
94:    * @param shouldAbort if the process should be aborted
95:    * @return a set of all found process instance items
96:    */
97:   public Set<Item> fetchIncidentItems(
98:       final IncidentFilter filter,
99:       final Authentication authentication,
100:       final Supplier<Boolean> shouldAbort) {
101: 
102:     LOG.debug("Fetching incident items with filter: {}", filter);
103:     return fetchEntityItems(new IncidentPageFetcher(), filter, authentication, shouldAbort);
104:   }
105: 
106:   /**
107:    * Fetches the incident items based on the provided process instance filter for the given
108:    * partitonId. This will return <b>ALL</b> incidents of the matching processInstances. The items
109:    * are fetched sequentially in pages. Depending on the overall size of the result, this can cause
110:    * multiple queries to the secondary database.
111:    *
112:    * @param filter the filter to use
113:    * @param authentication the authentication to use
114:    * @param shouldAbort if the process should be aborted
115:    * @return a set of all found incident items
116:    */
117:   public Set<Item> fetchIncidentItems(
118:       final int partitionId,
119:       final ProcessInstanceFilter filter,
120:       final Authentication authentication,
121:       final Supplier<Boolean> shouldAbort) {
122:     // first fetch all matching processInstances
123:     final var processInstanceKeyOperations =
124:         fetchProcessInstanceItems(partitionId, filter, authentication, shouldAbort).stream()
125:             .map(Item::processInstanceKey)
126:             .toList();
127: 
128:     // then fetch all incidents of the matching processInstances
129:     return getIncidentItemsOfProcessInstanceKeys(
130:         new ArrayList<>(processInstanceKeyOperations), authentication, shouldAbort);
131:   }
132: 
133:   private <F extends FilterBase> Set<Item> fetchEntityItems(
134:       final ItemPageFetcher<F> itemPageFetcher,
135:       final F filter,
136:       final Authentication authentication,
137:       final Supplier<Boolean> shouldAbort) {
138:     final var items = new LinkedHashSet<Item>();
139: 
140:     Object[] searchValues = null;
141:     while (true) {
142:       // Check if the batch operation is still present, could be canceled in the meantime
143:       if (shouldAbort.get()) {
144:         LOG.warn("Batch operation is no longer active, stopping query.");
145:         return Set.of();
146:       }
147: 
148:       final var result = itemPageFetcher.fetchItems(filter, searchValues, authentication);
149:       items.addAll(result.items);
150:       searchValues = result.lastSortValues();
151: 
152:       // the result.total count can be incorrect when using elasticsearch and could be capped at
153:       // 10_000. If the result.total is smaller than the queryPageSize, we can assume that we have
154:       // fetched all items. Otherwise, we fetch again until we fetch an empty page
155:       if (result.items.isEmpty() || result.total < queryPageSize) {
156:         break;
157:       }
158:     }
159: 
160:     return items;
161:   }
162: 
163:   private Set<Item> getIncidentItemsOfProcessInstanceKeys(
164:       final List<Long> processInstanceKeys,
165:       final Authentication authentication,
166:       final Supplier<Boolean> shouldAbort) {
167:     final Set<Item> incidents = new LinkedHashSet<>();
168: 
169:     final List<List<Long>> processInstanceKeysBatches =
170:         Lists.partition(processInstanceKeys, inClauseSize);
171: 
172:     for (final List<Long> processInstanceKeysBatch : processInstanceKeysBatches) {
173:       if (shouldAbort.get()) {
174:         return Set.of();
175:       }
176:       final var filter =
177:           new IncidentFilter.Builder().processInstanceKeyOperations(processInstanceKeysBatch).build();
178:       incidents.addAll(fetchIncidentItems(filter, authentication, shouldAbort));
179:     }
180: 
181:     return incidents;
182:   }
