228:   private final class ProcessInstancePageFetcher implements ItemPageFetcher<ProcessInstanceFilter> {
229:     @Override
230:     public ItemPage fetchItems(
231:         final ProcessInstanceFilter filter,
232:         final Object[] sortValues,
233:         final Authentication authentication) {
234:       final var securityContext =
235:           createSecurityContext(
236:               authentication, Authorization.of(a -> a.processDefinition().readProcessInstance()));
237:       final var page =
238:           SearchQueryPageBuilders.page().size(queryPageSize).searchAfter(sortValues).build();
239:       final var query =
240:           SearchQueryBuilders.processInstanceSearchQuery()
241:               .filter(filter)
242:               .page(page)
243:               .resultConfig(c -> c.onlyKey(true))
244:               .build();
245: 
246:       final SearchQueryResult<ProcessInstanceEntity> result =
247:           searchClientsProxy.withSecurityContext(securityContext).searchProcessInstances(query);
248: 
249:       return new ItemPage(
250:           result.items().stream()
251:               .map(pi -> new Item(pi.processInstanceKey(), pi.processInstanceKey()))
252:               .collect(Collectors.toList()),
253:           result.lastSortValues(),
254:           result.total());
255:     }
256:   }
