813:   private static List<MatchedDecisionRuleItem> toMatchedRules(
814:       final List<DecisionInstanceOutputEntity> decisionInstanceOutputEntities) {
815:     if (decisionInstanceOutputEntities == null) {
816:       return null;
817:     }
818:     final var outputEntitiesMappedByRule =
819:         decisionInstanceOutputEntities.stream()
820:             .collect(Collectors.groupingBy(e -> new RuleIdentifier(e.ruleId(), e.ruleIndex())));
821:     return outputEntitiesMappedByRule.entrySet().stream()
822:         .map(
823:             entry -> {
824:               final var ruleIdentifier = entry.getKey();
825:               final var outputs = entry.getValue();
826:               return new MatchedDecisionRuleItem()
827:                   .ruleId(ruleIdentifier.ruleId())
828:                   .ruleIndex(ruleIdentifier.ruleIndex())
829:                   .evaluatedOutputs(
830:                       outputs.stream()
831:                           .map(
832:                               output ->
833:                                   new EvaluatedDecisionOutputItem()
834:                                       .outputId(output.outputId())
835:                                       .outputName(output.outputName())
836:                                       .outputValue(output.outputValue()))
837:                           .toList());
838:             })
839:         .toList();
840:   }
