842:   private static DecisionInstanceStateEnum toDecisionInstanceStateEnum(
843:       final DecisionInstanceState state) {
844:     if (state == null) {
845:       return null;
846:     }
847:     return switch (state) {
848:       case EVALUATED -> DecisionInstanceStateEnum.EVALUATED;
849:       case FAILED -> DecisionInstanceStateEnum.FAILED;
850:       case UNSPECIFIED -> DecisionInstanceStateEnum.UNSPECIFIED;
851:       default -> DecisionInstanceStateEnum.UNKNOWN;
852:     };
853:   }
