270:   /**
271:    * Command to migrate a process instance to a different process definition.
272:    *
273:    * <p>The migration command contains a migration plan. Migration plan contains
274:    * targetProcessDefinitionKey to indicate which process definition to use for the migration.
275:    * Mapping instructions for the migration describe how to map elements from the source process
276:    * definition to the target process definition.
277:    *
278:    * <p>For example, let's consider we want to migrate process instance with key {@code 1}, target
279:    * process definition key {@code 2}, a source process definition with a service task with id
280:    * {@code "task1"} and the target process definition with a service task with id {@code "task2"}.
281:    * The migration command could be:
282:    *
283:    * <pre>{@code
284:    * {
285:    *  "processInstanceKey": 1,
286:    *  "migrationPlan": {
287:    *   "targetProcessDefinitionKey": 2,
288:    *   "mappingInstructions": [
289:    *    {
290:    *     "sourceElementId": "task1",
291:    *     "targetElementId": "task2"
292:    *    }
293:    *   ]
294:    *  }
295:    * }
296:    * }</pre>
297:    *
298:    * <pre>
299:    *
300:    * camundaClient
301:    *  .newMigrateProcessInstanceCommand(1L)
302:    *  .migrationPlan(2L)
303:    *  .addMappingInstruction("element1", "element2")
304:    *  .addMappingInstruction("element3", "element4")
305:    *  .send();
306:    * </pre>
307:    *
308:    * <pre>
309:    * final MigrationPlan migrationPlan =
310:    *         MigrationPlan.newBuilder()
311:    *             .withTargetProcessDefinitionKey(2L)
312:    *             .addMappingInstruction("element1", "element2")
313:    *             .addMappingInstruction("element3", "element4")
314:    *             .build();
315:    * camundaClient
316:    *  .newMigrateProcessInstanceCommand(1L)
317:    *  .migrationPlan(migrationPlan)
318:    *  .send();
319:    * </pre>
320:    *
321:    * @param processInstanceKey the key which refers to the process instance to migrate
322:    * @return a builder for the command
323:    */
324:   @ExperimentalApi("https://github.com/camunda/camunda/issues/14907")
325:   MigrateProcessInstanceCommandStep1 newMigrateProcessInstanceCommand(long processInstanceKey);
