156:   public static Either<List<String>, ProcessDefinitionStatisticsFilter>
157:       toProcessDefinitionStatisticsFilter(
158:           final long processDefinitionKey,
159:           final io.camunda.zeebe.gateway.protocol.rest.ProcessDefinitionStatisticsFilter filter) {
160:     final List<String> validationErrors = new ArrayList<>();
161: 
162:     final Either<List<String>, ProcessDefinitionStatisticsFilter.Builder> builder =
163:         toBaseProcessInstanceFilterFields(processDefinitionKey, filter);
164:     if (builder.isLeft()) {
165:       validationErrors.addAll(builder.getLeft());
166:     }
167: 
168:     if (filter != null) {
169:       if (filter.get$Or() != null && !filter.get$Or().isEmpty()) {
170:         for (final BaseProcessInstanceFilterFields or : filter.get$Or()) {
171:           final var orBuilder = toBaseProcessInstanceFilterFields(processDefinitionKey, or);
172:           if (orBuilder.isLeft()) {
173:             validationErrors.addAll(orBuilder.getLeft());
174:           } else {
175:             builder.get().addOrOperation(orBuilder.get().build());
176:           }
177:         }
178:       }
179:     }
180: 
181:     return validationErrors.isEmpty()
182:         ? Either.right(builder.get().build())
183:         : Either.left(validationErrors);
184:   }
