202:           .map(mapToOperations(OffsetDateTime.class))
203:           .ifPresent(builder::startDateOperations);
204:       ofNullable(filter.getEndDate())
205:           .map(mapToOperations(OffsetDateTime.class))
206:           .ifPresent(builder::endDateOperations);
207:       ofNullable(filter.getState())
208:           .map(mapToOperations(String.class, new ProcessInstanceStateConverter()))
209:           .ifPresent(builder::stateOperations);
210:       ofNullable(filter.getHasIncident()).ifPresent(builder::hasIncident);
211:       ofNullable(filter.getTenantId())
212:           .map(mapToOperations(String.class))
213:           .ifPresent(builder::tenantIdOperations);
