220:       ofNullable(filter.getHasRetriesLeft()).ifPresent(builder::hasRetriesLeft);
221:       ofNullable(filter.getElementId())
222:           .map(mapToOperations(String.class))
223:           .ifPresent(builder::flowNodeIdOperations);
224:       ofNullable(filter.getHasElementInstanceIncident())
225:           .ifPresent(builder::hasFlowNodeInstanceIncident);
226:       ofNullable(filter.getElementInstanceState())
227:           .map(mapToOperations(String.class))
228:           .ifPresent(builder::flowNodeInstanceStateOperations);
229:       ofNullable(filter.getIncidentErrorHashCode()).ifPresent(builder::incidentErrorHashCodes);
230:       if (!CollectionUtils.isEmpty(filter.getVariables())) {
231:         final Either<List<String>, List<VariableValueFilter>> either =
232:             toVariableValueFilters(filter.getVariables());
233:         if (either.isLeft()) {
234:           validationErrors.addAll(either.getLeft());
235:         } else {
236:           builder.variables(either.get());
237:         }
