507:   private static List<String> applyDecisionInstanceSortField(
508:       final DecisionInstanceSearchQuerySortRequest.FieldEnum field,
509:       final DecisionInstanceSort.Builder builder) {
510:     final List<String> validationErrors = new ArrayList<>();
511:     if (field == null) {
512:       validationErrors.add(ERROR_SORT_FIELD_MUST_NOT_BE_NULL);
513:     } else {
514:       switch (field) {
515:         case DECISION_INSTANCE_KEY -> builder.decisionInstanceKey();
516:         case DECISION_INSTANCE_ID -> builder.decisionInstanceId();
517:         case STATE -> builder.state();
518:         case EVALUATION_DATE -> builder.evaluationDate();
519:         case EVALUATION_FAILURE -> builder.evaluationFailure();
520:         case PROCESS_DEFINITION_KEY -> builder.processDefinitionKey();
521:         case PROCESS_INSTANCE_KEY -> builder.processInstanceKey();
522:         case DECISION_DEFINITION_KEY -> builder.decisionDefinitionKey();
523:         case DECISION_DEFINITION_ID -> builder.decisionDefinitionId();
524:         case DECISION_DEFINITION_NAME -> builder.decisionDefinitionName();
525:         case DECISION_DEFINITION_VERSION -> builder.decisionDefinitionVersion();
526:         case DECISION_DEFINITION_TYPE -> builder.decisionDefinitionType();
527:         case TENANT_ID -> builder.tenantId();
528:         default -> validationErrors.add(ERROR_UNKNOWN_SORT_BY.formatted(field));
529:       }
530:     }
531:     return validationErrors;
532:   }
