1482:   private static Either<List<String>, List<VariableValueFilter>> toVariableValueFilters(
1483:       final List<VariableValueFilterRequest> filters) {
1484:     if (CollectionUtils.isEmpty(filters)) {
1485:       return Either.right(List.of());
1486:     }
1487: 
1488:     final List<String> validationErrors = new ArrayList<>();
1489:     final List<VariableValueFilter> variableValueFilters =
1490:         filters.stream()
1491:             .flatMap(
1492:                 filter -> {
1493:                   if (filter.getName() == null) {
1494:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_NAME);
1495:                   }
1496:                   if (filter.getValue() == null
1497:                       || filter.getValue().equals(EMPTY_ADVANCED_STRING_FILTER)
1498:                       || filter.getValue().equals(EMPTY_BASIC_STRING_FILTER)) {
1499:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_VALUE);
1500:                   }
1501:                   // if there is no validation error overall, process the filter
1502:                   return validationErrors.isEmpty()
1503:                       ? toVariableValueFilters(filter.getName(), filter.getValue()).stream()
1504:                       : Stream.empty();
1505:                 })
1506:             .toList();
1507:     return validationErrors.isEmpty()
1508:         ? Either.right(variableValueFilters)
1509:         : Either.left(validationErrors);
