1339:   private static void deployProcess(
1340:       final String processId,
1341:       final String resourceName,
1342:       final String userTaskName,
1343:       final String candidateGroup,
1344:       final String candidateUser) {
1345:     final DateTimeFormatter dateFormat =
1346:         DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
1347:     final ZoneId utcZoneId = ZoneId.of("UTC");
1348: 
1349:     final LocalDateTime now = LocalDateTime.now(utcZoneId);
1350:     final LocalDateTime dayBefore = now.minusDays(1);
1351: 
1352:     camundaClient
1353:         .newDeployResourceCommand()
1354:         .addProcessModel(
1355:             Bpmn.createExecutableProcess(processId)
1356:                 .startEvent()
1357:                 .userTask(userTaskName)
1358:                 .zeebeUserTask()
1359:                 .zeebeDueDate(dayBefore.format(dateFormat))
1360:                 .zeebeFollowUpDate(dayBefore.format(dateFormat))
1361:                 .zeebeCandidateGroups(candidateGroup)
1362:                 .zeebeCandidateUsers(candidateUser)
1363:                 .endEvent()
1364:                 .done(),
1365:             resourceName)
1366:         .send()
1367:         .join();
1368:   }
